style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url(https://w0.peakpx.com/wallpaper/935/1012/HD-wallpaper-aoba-seragaki-dramatical-murder-headphones-sleeping.jpg); /* Replace with your image URL */
        background-size: cover;
        background-attachment: fixed;
        background-position: center center;
    }

    /* Optional: make background visible by removing Roblox’s white backgrounds */
    .container-main, .navbar, .content, .footer-container, #nav-content, #header, .section, .row {
        background: transparent !important;
    }

    /* Optional: make text easier to read */
    * {
        color: white !important;
        text-shadow: 1px 1px 2px black;
    }
}
